class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])  # Path compression
        return self.parent[x]

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py:
            return
        # Union by rank
        if self.rank[px] < self.rank[py]:
            self.parent[px] = py
        elif self.rank[px] > self.rank[py]:
            self.parent[py] = px
        else:
            self.parent[py] = px
            self.rank[px] += 1

def findRedundantConnection(edges):
    uf = UnionFind(len(edges) + 1)

    for u, v in edges:
        if uf.find(u) == uf.find(v):
            return [u, v]  # Cycle found
        uf.union(u, v)

    return []

def findCircleNum(isConnected):
    n = len(isConnected)
    uf = UnionFind(n)

    for i in range(n):
        for j in range(n):
            if isConnected[i][j] == 1:
                uf.union(i, j)

    # Count unique roots
    roots = set(uf.find(i) for i in range(n))
    return len(roots)
